// lamina's docs site (todo B7a): Starlight, with the @laminapdf/sdk API reference generated by
// TypeDoc at build time and every internal link checked (starlight-links-validator, plus
// plugins/integrations.mjs for what it can't see). Code on the pages is read from the tested
// example files (src/components/Snippet.astro), the code table from fixtures/codes.json, and the
// code pages from docs/errors/ (src/pages/reference/codes/[code].astro, plugins/error-pages.mjs).
//
// Build-time settings (environment variables):
// - LAMINA_DOCS_GITHUB=1 adds the links to GitHub (the repository in the header, "Edit page",
//   TypeDoc's "Defined in" source links). Off by default: while the repository is private they
//   would 404 for readers.
// - LAMINA_DOCS_TYPEDOC=0 leaves the TypeDoc reference out (the package's `typecheck` uses it,
//   so the TypeScript checks generate the reference only once, in the build).
import { fileURLToPath } from "node:url";
import starlight from "@astrojs/starlight";
import { defineConfig } from "astro/config";
import starlightLinksValidator from "starlight-links-validator";
import starlightTypeDoc, { typeDocSidebarGroup } from "starlight-typedoc";
import { checkedLinks, examplePdfs, inlineScriptHashes } from "./plugins/integrations.mjs";
import { REPOSITORY } from "./plugins/repository.mjs";

const ROOT = new URL("../../", import.meta.url);
const GITHUB = process.env.LAMINA_DOCS_GITHUB === "1";
const TYPEDOC = process.env.LAMINA_DOCS_TYPEDOC !== "0";

const typeDoc = starlightTypeDoc({
  entryPoints: [fileURLToPath(new URL("packages/sdk/src/index.ts", ROOT))],
  tsconfig: fileURLToPath(new URL("packages/sdk/tsconfig.build.json", ROOT)),
  output: "reference/sdk",
  sidebar: { label: "@laminapdf/sdk (TypeDoc)", collapsed: true },
  typeDoc: {
    // The wasm-bindgen types come from @laminapdf/wasm's dist/, which only `cargo xtask wasm`
    // builds: without it the records are named but not expanded, and the build goes on.
    skipErrorChecking: true,
    excludeInternal: true,
    excludePrivate: true,
    ...(GITHUB
      ? { gitRevision: "main", sourceLinkTemplate: `${REPOSITORY}/blob/main/{path}#L{line}` }
      : { disableSources: true }),
  },
});

// A default export because that is how Astro reads its configuration.
export default defineConfig({
  // Production's address: canonical links and the sitemap use it (previews too; they're noindex).
  site: "https://docs.laminapdf.com",
  // Telemetry is off in the package scripts (ASTRO_TELEMETRY_DISABLED).
  devToolbar: { enabled: false },
  // Moved pages keep their old URLs (static redirects; Workers static assets ignore _redirects).
  redirects: { "/guides/errors-and-warnings/": "/concepts/errors-and-warnings/" },
  integrations: [
    starlight({
      title: "lamina",
      description:
        "Create, read, edit and save PDFs from Rust and TypeScript: one Rust core, as WebAssembly in browsers, Node, Deno, Bun and Cloudflare Workers.",
      ...(GITHUB
        ? {
            social: [{ icon: "github", label: "GitHub", href: REPOSITORY }],
            editLink: { baseUrl: `${REPOSITORY}/edit/main/apps/docs/` },
          }
        : {}),
      lastUpdated: false,
      // The Paper design language (docs/design/paper/design-language.md): tokens, fonts, titles.
      customCss: ["./src/styles/paper.css"],
      plugins: [
        starlightLinksValidator({
          errorOnLocalLinks: true,
          // Not pages: plugins/integrations.mjs `checkedLinks` checks these (and the code pages).
          exclude: ["/examples/pdf/*", "/reference/codes/*/"],
        }),
        ...(TYPEDOC ? [typeDoc] : []),
      ],
      // The docs as a story (quality plan §3): the order is a decision, so every page is listed.
      // Q1i, Q1m and Q1j rename the guides and add the recipes and troubleshooting.
      sidebar: [
        {
          label: "Start here",
          items: [
            { label: "What is lamina", link: "/" },
            { label: "Install", slug: "install" },
            { label: "Your first PDF", slug: "start/first-pdf" },
          ],
        },
        {
          label: "Your runtime",
          items: [
            { label: "Browser and bundlers", slug: "quick-start/browser" },
            { label: "Node", slug: "quick-start/node" },
            { label: "Deno", slug: "quick-start/deno" },
            { label: "Bun", slug: "quick-start/bun" },
            { label: "Cloudflare Workers", slug: "quick-start/workers" },
            { label: "Rust", slug: "quick-start/rust" },
          ],
        },
        {
          label: "Concepts",
          items: [
            { label: "How lamina thinks about a PDF", slug: "concepts/how-lamina-thinks" },
            { label: "Pages and coordinates", slug: "concepts/pages-and-coordinates" },
            { label: "Errors and warnings", slug: "concepts/errors-and-warnings" },
          ],
        },
        {
          label: "Create PDFs",
          items: [
            { label: "Text and fonts", slug: "guides/fonts-and-text" },
            { label: "Shapes, colour and images", slug: "guides/images-and-vectors" },
            { label: "Links, outlines and metadata", slug: "guides/links-outlines-and-metadata" },
            { label: "Accessible PDFs", slug: "guides/accessible-pdfs" },
            { label: "Archival PDFs", slug: "guides/archival-pdfs" },
          ],
        },
        {
          label: "Read and edit PDFs",
          items: [
            { label: "Open, edit and save", slug: "guides/open-edit-and-save" },
            { label: "Open password-protected files", slug: "guides/encrypted-files" },
            { label: "Open files you don't trust", slug: "guides/limits" },
          ],
        },
        {
          label: "Production",
          items: [{ label: "Keep the page responsive", slug: "guides/off-the-main-thread" }],
        },
        { label: "Examples", link: "/examples/" },
        {
          label: "Reference",
          items: [
            ...(TYPEDOC ? [typeDocSidebarGroup] : []),
            { label: "Rust API (rustdoc)", slug: "reference/rust" },
            { label: "Error and warning codes", slug: "reference/codes" },
            { label: "Glossary", slug: "reference/glossary" },
          ],
        },
      ],
    }),
    examplePdfs(new URL("fixtures/golden/examples/", ROOT)),
    checkedLinks,
    inlineScriptHashes,
  ],
});
